module TopModule (
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // State encoding: 4 states to detect sequence 1101
    typedef enum logic [1:0] {
        S_IDLE   = 2'b00,
        S_1      = 2'b01,
        S_11     = 2'b10,
        S_110    = 2'b11
    } state_t;

    logic [1:0] state, next_state;
    logic found;

    // State register (synchronous reset)
    always_ff @(posedge clk) begin
        if (reset)
            state <= S_IDLE;
        else
            state <= next_state;
    end

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            S_IDLE: begin
                if (data == 1'b1)
                    next_state = S_1;
                else
                    next_state = S_IDLE;
            end
            S_1: begin
                if (data == 1'b1)
                    next_state = S_11;
                else
                    next_state = S_IDLE;
            end
            S_11: begin
                if (data == 1'b0)
                    next_state = S_110;
                else
                    next_state = S_11; // stay on another '1'
            end
            S_110: begin
                if (data == 1'b1)
                    next_state = S_IDLE; // found 1101
                else
                    next_state = S_IDLE;
            end
            default: next_state = S_IDLE;
        endcase
    end

    // Output logic: start_shifting goes high when sequence is found
    // and stays high until reset
    assign start_shifting = found;

    // Sequence detection flag
    always_ff @(posedge clk) begin
        if (reset)
            found <= 1'b0;
        else if (state == S_110 && data == 1'b1)
            found <= 1'b1;
    end

endmodule

