module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Byte shift register: holds the last 3 valid bytes
    // reg1 = first byte (byte1), reg2 = second byte (byte2), reg3 = third byte (byte3)
    logic [7:0] reg1, reg2, reg3;

    // Next-state logic (combinational)
    always_comb begin
        case (state)
            IDLE: begin
                // If we see a byte with bit 3 set, start a new message
                if (in[3]) begin
                    next_state = BYTE1;
                end else begin
                    next_state = IDLE;
                end
            end
            BYTE1: begin
                // Shift in the current byte as byte1, move to byte2
                next_state = BYTE2;
            end
            BYTE2: begin
                // Shift in the current byte as byte2, move to byte3
                next_state = BYTE3;
            end
            BYTE3: begin
                // After receiving the third byte, assert done next cycle, then go IDLE
                next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase
    end

    // State flip-flops (sequential, positive edge, synchronous reset)
    always_ff @(posedge clk) begin
        if (reset) begin
            state     <= IDLE;
            reg1      <= 8'b0;
            reg2      <= 8'b0;
            reg3      <= 8'b0;
            out_bytes <= 24'b0;
            done      <= 1'b0;
        end else begin
            state <= next_state;

            case (state)
                IDLE: begin
                    // Reset registers when not in a message
                    reg1 <= 8'b0;
                    reg2 <= 8'b0;
                    reg3 <= 8'b0;
                    done <= 1'b0;
                end
                BYTE1: begin
                    // Capture the first byte (the one that had in[3]=1)
                    reg1 <= in;
                    done <= 1'b0;
                end
                BYTE2: begin
                    // Shift byte1 -> byte2, capture new byte as byte1? 
                    // Actually we need to keep byte1 and capture byte2 as the new second byte.
                    // The specification says: "out_bytes[23:16] is the first byte, 
                    // out_bytes[15:8] is the second byte, etc."
                    // So we need to remember byte1 while we receive byte2 and byte3.
                    // We'll shift: reg1 stays as byte1, reg2 gets the current in.
                    reg2 <= in;
                    done <= 1'b0;
                end
                BYTE3: begin
                    // Shift byte2 -> byte3? Wait, we need three bytes total.
                    // We have reg1 (byte1), reg2 (byte2), and now we capture reg3 (byte3).
                    reg3 <= in;
                    // Now we have all three bytes; assert done in the next cycle.
                    done <= 1'b1;
                    // Output the 24-bit message immediately
                    out_bytes <= {reg1, reg2, reg3};
                end
            endcase
        end
    end

    // The done signal must be valid in the cycle immediately after the third byte was received.
    // The above always_ff block asserts done in the BYTE3 state, which is the cycle after
    // the third byte is latched. This matches the requirement.

endmodule

