    output f
);

    // Internal signal to hold the combinational result
    logic f_internal;

    // Combinational logic implementing the Karnaugh map
    always_comb begin
        case (x)
            // x[3:4] = 00: d (don't-care)
            // x[3:4] = 01: f = 1 when x[1]=0, x[2]=1 (minterm 0101); f = 0 when x[1]=1, x[2]=0 (minterm 0110)
            4'b00xx: f_internal = 1'b0;
            4'b0101: f_internal = 1'b1;
            4'b0110: f_internal = 1'b0;
            // x[3:4] = 11: f = 1 when x[1]=1, x[2]=1 (minterm 1111) or x[1]=1, x[2]=0 (minterm 1101, don't-care)
            //        f = 0 when x[1]=0, x[2]=1 (minterm 1101, don't-care may be treated as 0)
            4'b1101: f_internal = 1'b1;
            4'b1111: f_internal = 1'b1;
            4'b1100: f_internal = 1'b0;  // don't-care treated as 0 for simplicity
            // x[3:4] = 10: f = 1 when x[1]=1, x[2]=1 (minterm 1011, don't-care) or x[1]=1, x[2]=0 (minterm 1010, don't-care)
            //        f = 0 when x[1]=0, x[2]=1 (minterm 1001, don't-care) — simplified to 1'b1 for remaining cases
            4'b1011: f_internal = 1'b1;
            4'b1010: f_internal = 1'b1;
            4'b1001: f_internal = 1'b1;  // don't-care treated as 1
            default: f_internal = 1'b0;
        endcase
    end

    // Assign internal signal to output port
    assign f = f_internal;

