    always_comb begin
        case (state)
            A: next_state = in ? B : A;
            B: next_state = B; // in has no effect on next state from B
            C: next_state = in ? D : A;
            D: next_state = in ? C : B;
            default: next_state = A;
        endcase
    end

    // Output logic (Moore machine: output depends only on state)
    always_comb begin
        case (state)
            D: out = 1'b1;
            default: out = 1'b0;
        endcase
    end

    // Next-state flip-flops (sequential, positive edge-triggered)
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            state <= A;
        else
            state <= next_state;
    end

