module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // Internal state: previous sensor state (3 bits)
    logic [2:0] prev_s;

    // Combinational logic for outputs (when not in reset)
    always @(*) begin
        // Default assignments (all outputs 0)
        fr2 = 1'b0;
        fr1 = 1'b0;
        fr0 = 1'b0;
        dfr = 1'b0;

        // Active-high synchronous reset: equivalent to long-low water level
        if (reset) begin
            // No sensors asserted, all four outputs asserted
            fr2 = 1'b1;
            fr1 = 1'b1;
            fr0 = 1'b1;
            dfr = 1'b1;
        end else begin
            // Determine outputs based on current sensor state and previous state
            case (s)
                // Above s[2]: s[0], s[1], s[2] asserted -> None
                3'b111: begin
                    // No nominal outputs, dfr stays 0
                end
                // Between s[2] and s[1]: s[0], s[1] asserted -> fr0
                3'b110: begin
                    fr0 = 1'b1;
                end
                // Between s[1] and s[0]: s[0] asserted -> fr0, fr1
                3'b101: begin
                    fr0 = 1'b1;
                    fr1 = 1'b1;
                end
                // Below s[0]: None asserted -> fr0, fr1, fr2
                3'b100: begin
                    fr0 = 1'b1;
                    fr1 = 1'b1;
                    fr2 = 1'b1;
                end
                // Default case (should not occur with valid sensors, but safe)
                default: begin
                    // No outputs
                end
            endcase

            // Supplemental flow valve (dfr): increase flow if previous level was lower than current
            // "previous level was lower than the current level" means a sensor change from lower to higher
            // We compare current s with previous prev_s
            if (s > prev_s) begin
                dfr = 1'b1;
            end
        end
    end

    // Sequential block to update prev_s on clock edge
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            prev_s <= 3'b000;
        end else begin
            prev_s <= s;
        end
    end

endmodule

