                begin
                    if (d == 1'b0)
                        S_nxt = 10'b0000000001; // stay in S
                    else
                        S_nxt = 10'b0000000010; // go to S1
                end

            // S1 state
            10'b0000000010: // S1
                begin
                    if (d == 1'b0)
                        S_nxt = 10'b0000000001; // go to S
                    else
                        S_nxt = 10'b0000000100; // go to S11
                end

            // S11 state
            10'b0000000100: // S11
                begin
                    if (d == 1'b0)
                        S_nxt = 10'b0000001000; // go to S110
                    else
                        S_nxt = 10'b0000000100; // stay in S11
                end

            // S110 state
            10'b0000001000: // S110
                begin
                    if (d == 1'b0)
                        S_nxt = 10'b0000000001; // go to S
                    else
                        S_nxt = 10'b1000000000; // go to B0
                end

            // B0 state (always go to B1)
            10'b1000000000: // B0
                begin
                    S_nxt = 10'b0100000000; // B1
                end

            // B1 state (always go to B2)
            10'b0100000000: // B1
                begin
                    S_nxt = 10'b0010000000; // B2
                end

            // B2 state (always go to B3)
            10'b0010000000: // B2
                begin
                    S_nxt = 10'b0001000000; // B3
                end

            // B3 state (always go to Count)
            10'b0001000000: // B3
                begin
                    S_nxt = 10'b0000100000; // Count
                end

            // Count state
            10'b0000100000: // Count
                begin
                    if (done_counting == 1'b0)
                        S_nxt = 10'b0000100000; // stay in Count
                    else
                        S_nxt = 10'b0000010000; // go to Wait
                end

            // Wait state
            10'b0000010000: // Wait
                begin
                    if (ack == 1'b1)
                        S_nxt = 10'b0000000001; // go to S
                    else
                        S_nxt = 10'b0000010000; // stay in Wait
                end

            default: S_nxt = 10'b0000000001; // reset to S
        endcase
    end

    // ---------- Output logic (Moore machine) ----------
    // done: asserted only in S state
    assign done = (state == 10'b0000000001);

    // counting: asserted only in Count state
    assign counting = (state == 10'b0000100000);

    // shift_ena: asserted in B0, B1, B2, B3 states
    assign shift_ena = (state == 10'b1000000000) | 
                       (state == 10'b0100000000) | 
                       (state == 10'b0010000000) | 
                       (state == 10'b0001000000);

    // ---------- Next-state one-hot generation ----------
    // S_next
    always_comb begin
        S_nxt = 10'b0;
        if (state == 10'b0000000001) begin // S
            if (d == 1'b0) S_nxt = 10'b0000000001;
            else          S_nxt = 10'b0000000010;
        end
        else if (state == 10'b0000000010) begin // S1
            if (d == 1'b0) S_nxt = 10'b0000000001;
            else          S_nxt = 10'b0000000100;
        end
        else if (state == 10'b0000000100) begin // S11
            if (d == 1'b0) S_nxt = 10'b0000001000;
            else          S_nxt = 10'b0000000100;
        end
        else if (state == 10'b0000001000) begin // S110
            if (d == 1'b0) S_nxt = 10'b0000000001;
            else          S_nxt = 10'b1000000000;
        end
        else if (state == 10'b1000000000) begin // B0
            S_nxt = 10'b0100000000; // B1
        end
        else if (state == 10'b0100000000) begin // B1
            S_nxt = 10'b0010000000; // B2
        end
        else if (state == 10'b0010000000) begin // B2
            S_nxt = 10'b0001000000; // B3
        end
        else if (state == 10'b0001000000) begin // B3
            S_nxt = 10'b0000100000; // Count
        end
        else if (state == 10'b0000100000) begin // Count
            if (done_counting == 1'b0) S_nxt = 10'b0000100000;
            else                       S_nxt = 10'b0000010000;
        end
        else if (state == 10'b0000010000) begin // Wait
            if (ack == 1'b1) S_nxt = 10'b0000000001;
            else            S_nxt = 10'b0000010000;
        end
    end

    // S1_next
    always_comb begin
        S1_nxt = 10'b0;
        if (state == 10'b0000000010) begin // S1
            if (d == 1'b1) S1_nxt = 10'b0000000100;
        end
    end

    // S11_next
    always_comb begin
        S11_nxt = 10'b0;
        if (state == 10'b0000000100) begin // S11
            if (d == 1'b1) S11_nxt = 10'b0000000100;
        end
    end

    // S110_next
    always_comb begin
        S110_nxt = 10'b0;
        if (state == 10'b0000001000) begin // S110
            if (d == 1'b1) S110_nxt = 10'b1000000000;
        end
    end

    // B0_next (always asserted when in B0, transitioning to B1)
    always_comb begin
        B0_nxt = 10'b0;
        if (state == 10'b1000000000) begin // B0
            B0_nxt = 10'b0100000000; // B1
        end
    end

    // B1_next (always asserted when in B1, transitioning to B2)
    always_comb begin
        B1_nxt = 10'b0;
        if (state == 10'b0100000000) begin // B1
            B1_nxt = 10'b0010000000; // B2
        end
    end

    // B2_next (always asserted when in B2, transitioning to B3)
    always_comb begin
        B2_nxt = 10'b0;
        if (state == 10'b0010000000) begin // B2
            B2_nxt = 10'b0001000000; // B3
        end
    end

    // B3_next (always asserted when in B3, transitioning to Count)
    always_comb begin
        B3_nxt = 10'b0;
        if (state == 10'b0001000000) begin // B3
            B3_nxt = 10'b0000100000; // Count
        end
    end

    // Count_next (asserted when transitioning to Count state)
    always_comb begin
        Count_nxt = 10'b0;
        if (state == 10'b0000010000) begin // Wait & ack=1
            Count_nxt = 10'b0000100000;
        end
        else if (state == 10'b0000100000) begin // Count & done_counting=0
            Count_nxt = 10'b0000100000;
        end
    end

    // Wait_next (asserted when transitioning to Wait state)
    always_comb begin
        Wait_nxt = 10'b0;
        if (state == 10'b0000100000) begin // Count & done_counting=1
            Wait_nxt = 10'b0000010000;
        end
    end

endmodule

