module TopModule (
    input  clk,
    input  reset,
    output ena   // 3 bits: enable for tens, hundreds, thousands
    output q     // 16 bits: 4-digit BCD
);

    // Internal registers for the 4 BCD digits
    logic [3:0] ones;    // q[3:0]
    logic [3:0] tens;    // q[7:4]
    logic [3:0] hundreds;// q[11:8]
    logic [3:0] thousands;// q[15:12]

    // ena[0] is not used (ones digit always increments when not reset)
    // ena[1] -> tens enable, ena[2] -> hundreds enable, ena[3] -> thousands enable
    // Since ena is 3 bits, we map: ena[0]=tens, ena[1]=hundreds, ena[2]=thousands
    logic [2:0] ena_int;

    // BCD increment logic for a single digit with carry-out
    // If ena is high, the digit increments; otherwise holds value.
    // Carry-out is 1 when the digit was 9 and we are incrementing.
    always_ff @(posedge clk) begin
        if (reset) begin
            ones    <= 4'b0;
            tens    <= 4'b0;
            hundreds<= 4'b0;
            thousands<= 4'b0;
            ena_int <= 3'b000;
        end else begin
            // --- ones digit ---
            // ones always increments (unless reset). ena for tens is generated when ones rolls over from 9.
            if (ones == 4'd9)
                ones <= 4'd0;
            else
                ones <= ones + 1'b1;

            // ena[0] (tens enable) is high when ones just rolled over from 9
            if (ones == 4'd9)
                ena_int[0] <= 1'b1;
            else
                ena_int[0] <= 1'b0;

            // --- tens digit ---
            if (ena_int[0]) begin // increment tens only if ones rolled over
                if (tens == 4'd9)
                    tens <= 4'd0;
                else
                    tens <= tens + 1'b1;
            end else begin
                tens <= tens; // hold
            end

            // ena[1] (hundreds enable) is high when tens rolls over from 9
            if (ena_int[0] && tens == 4'd9)
                ena_int[1] <= 1'b1;
            else if (!ena_int[0])
                ena_int[1] <= 1'b0;
            else
                ena_int[1] <= 1'b0; // tens incremented but not rolled over

            // --- hundreds digit ---
            if (ena_int[1]) begin // increment hundreds only if tens rolled over
                if (hundreds == 4'd9)
                    hundreds <= 4'd0;
                else
                    hundreds <= hundreds + 1'b1;
            end else begin
                hundreds <= hundreds; // hold
            end

            // ena[2] (thousands enable) is high when hundreds rolls over from 9
            if (ena_int[1] && hundreds == 4'd9)
                ena_int[2] <= 1'b1;
            else if (!ena_int[1])
                ena_int[2] <= 1'b0;
            else
                ena_int[2] <= 1'b0; // hundreds incremented but not rolled over

            // --- thousands digit ---
            if (ena_int[2]) begin // increment thousands only if hundreds rolled over
                if (thousands == 4'd9)
                    thousands <= 4'd0;
                else
                    thousands <= thousands + 1'b1;
            end else begin
                thousands <= thousands; // hold
            end
        end
    end

    // Assign output ports
    // q is the concatenation of thousands, hundreds, tens, ones
    assign q = {thousands, hundreds, tens, ones};

    // ena output: ena[0] -> tens enable, ena[1] -> hundreds enable, ena[2] -> thousands enable
    assign ena = ena_int;

endmodule

