module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [3:0] {
        WALK_LEFT   = 4'b0001,
        WALK_RIGHT  = 4'b0010,
        FALLING     = 4'b0100,
        DIGGING     = 4'b1000,
        SPLATTERED  = 4'b0000
    } state_t;

    // State registers
    state_t state, next_state;

    // Counter for fall duration
    logic [4:0] fall_counter, next_fall_counter;

    // Register to remember the walking direction before falling or digging
    logic [1:0] dir_reg, next_dir_reg; // 0 = left, 1 = right

    // Output logic (Moore machine - outputs are registered)
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            walk_left   <= 1'b0;
            walk_right  <= 1'b0;
            aaah        <= 1'b0;
            digging     <= 1'b0;
        end else begin
            walk_left   <= (state == WALK_LEFT);
            walk_right  <= (state == WALK_RIGHT);
            aaah        <= (state == FALLING);
            digging     <= (state == DIGGING);
        end
    end

    // Next state and counter logic
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state       <= WALK_LEFT;
            fall_counter <= 5'd0;
            dir_reg     <= 2'd0; // initially walking left
        end else begin
            // Default: keep current state
            next_state   <= state;
            next_fall_counter <= fall_counter;
            next_dir_reg <= dir_reg;

            // Priority: fall > dig > switch directions
            // 1. Fall handling (highest precedence)
            if (ground == 1'b0) begin
                // Currently falling or just fell
                if (state == FALLING || state == DIGGING) begin
                    // Continuing to fall
                    next_state <= FALLING;
                    // Increment fall counter if we were already falling
                    if (state == FALLING)
                        next_fall_counter <= fall_counter + 5'd1;
                    else
                        next_fall_counter <= 5'd1; // Started falling from dig
                end else begin
                    // ground went from 1 to 0 while walking
                    next_state <= FALLING;
                    next_fall_counter <= 5'd1;
                end
            end else begin
                // ground == 1
                if (state == FALLING) begin
                    // Check splatter condition: fell > 20 cycles
                    if (fall_counter >= 5'd20) begin
                        next_state <= SPLATTERED;
                        next_fall_counter <= 5'd0;
                    end else begin
                        // Ground reappeared while falling - resume walking
                        // in the same direction as before the fall
                        // Restore the direction we were going before falling
                        if (dir_reg == 2'd0) begin
                            next_state <= WALK_LEFT;
                        end else begin
                            next_state <= WALK_RIGHT;
                        end
                        next_fall_counter <= 5'd0;
                    end
                end else if (state == DIGGING) begin
                    // Digging on ground - stop digging, start walking
                    // in the current walking direction (dir_reg)
                    next_state <= (dir_reg == 2'd0) ? WALK_LEFT : WALK_RIGHT;
                end
            end

            // 2. Dig handling (second precedence)
            // Only if not falling and not splattered
            if (state != FALLING && state != SPLATTERED) begin
                if (dig == 1'b1 && ground == 1'b1) begin
                    next_state <= DIGGING;
                    // Remember the walking direction before we start digging
                    next_dir_reg <= dir_reg;
                end
            end

            // 3. Direction switching (lowest precedence)
            // Only if not falling, not splattered, and not digging
            if (state != FALLING && state != SPLATTERED && state != DIGGING) begin
                // Determine new direction based on bumps
                // If bumped on left -> walk right
                // If bumped on right -> walk left
                // If bumped on both -> switch directions
                if (bump_left == 1'b1 || bump_right == 1'b1) begin
                    if (bump_left == 1'b1 && bump_right == 1'b1) begin
                        // Bumped both sides - switch direction
                        if (state == WALK_LEFT)
                            next_state <= WALK_RIGHT;
                        else
                            next_state <= WALK_LEFT;
                    end else if (bump_left == 1'b1) begin
                        // Bumped left - walk right
                        next_state <= WALK_RIGHT;
                    end else if (bump_right == 1'b1) begin
                        // Bumped right - walk left
                        next_state <= WALK_LEFT;
                    end
                end
            end

            state       <= next_state;
            fall_counter <= next_fall_counter;
            dir_reg     <= next_dir_reg;
        end
    end

endmodule

