module TopModule (
    input  logic clk,    // Assuming logic type as per modern SV, but problem says "one bit".
    input  logic resetn,
    input  logic x,
    input  logic y,
    output logic f,
    output logic g
);

// Using 'logic' for ports and wires is standard for synthesizable SV (IEEE 1800-2012)
// The prompt says "All input and output ports are one bit unless otherwise specified."
// I will declare ports as 'logic' internally, but for port declarations, 'wire' or 'logic' works.
// Icarus Verilog -g2012 supports 'logic' ports.

    // State declaration
    typedef enum logic [3:0] {
        S_A   = 4'b0000, // Reset state
        S_B   = 4'b0001, // f=1 pulse
        S_C0  = 4'b0010, // Monitor x: initial
        S_C1  = 4'b0011, // Monitor x: detected 1
        S_C2  = 4'b0100, // Monitor x: detected 1,0
        S_C3  = 4'b0101, // Monitor x: detected 1,0,1
        S_D0  = 4'b0110, // g=1: check y (1st cycle)
        S_D1  = 4'b0111, // g=1: check y (2nd cycle)
        S_KEEP= 4'b1000, // g=1 permanently
        S_G0  = 4'b1001  // g=0 permanently
    } state_t;

    state_t state, next_state;

    // Next-state logic
    always_comb begin
        // Default assignment: stay in current state
        next_state = state;

        case (state)
            S_A: begin
                // If reset is de-asserted, move to S_B
                if (resetn) begin
                    next_state = S_B;
                end
            end

            S_B: begin
                // f is 1 for one cycle, then move to monitor x
                next_state = S_C0;
            end

            S_C0: begin
                // Looking for the first '1' of the sequence 1,0,1
                if (x == 1'b1) begin
                    next_state = S_C1;
                end else begin
                    // Stay in S_C0
                    next_state = S_C0;
                end
            end

            S_C1: begin
                // We have seen a '1'. Looking for '0'.
                if (x == 1'b0) begin
                    next_state = S_C2;
                end else if (x == 1'b1) begin
                    // If we see another '1', we are still looking for the start of the pattern,
                    // but since we already have a '1', we stay in S_C1 (or could be interpreted as
                    // the new '1' starting the sequence. Usually, for "1,0,1", seeing 1,1 resets
                    // the "waiting for 0" part, but the first '1' is consumed.
                    // Let's assume: if we see 1, we are still in the state where we have seen a 1.
                    next_state = S_C1;
                end else begin
                    next_state = S_C1;
                end
            end

            S_C2: begin
                // We have seen '1', '0'. Looking for '1'.
                if (x == 1'b1) begin
                    // Pattern 1,0,1 detected. Move to Y monitor.
                    next_state = S_C3;
                end else if (x == 1'b0) begin
                    // Pattern broken. Go back to initial state.
                    next_state = S_C0;
                end
            end

            S_C3: begin
                // Pattern detected. Transition to Y monitor (S_D0) on next cycle.
                next_state = S_D0;
            end

            S_D0: begin
                // g has just been set to 1 (or is being set). Monitor y.
                // "If y has the value 1 within at most two clock cycles"
                if (y == 1'b1) begin
                    // y=1 within the allowed window. Maintain g=1 permanently.
                    next_state = S_KEEP;
                end else begin
                    // y=0. Move to S_D1 to wait for the second cycle.
                    next_state = S_D1;
                end
            end

            S_D1: begin
                // One cycle of y=0 has passed. Check y again.
                if (y == 1'b1) begin
                    // y=1 within the two-cycle window. Maintain g=1 permanently.
                    next_state = S_KEEP;
                end else begin
                    // y=0 for two cycles. Set g=0 permanently.
                    next_state = S_G0;
                end
            end

            S_KEEP: begin
                // g=1 forever. Stay here.
                next_state = S_KEEP;
            end

            S_G0: begin
                // g=0 forever. Stay here.
                next_state = S_G0;
            end

            default: begin
                next_state = S_A;
            end
        endcase
    end

    // State register (Positive edge triggered, Synchronous active low reset)
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= S_A;
        end else begin
            state <= next_state;
        end
    end

    // Output logic
    // f is 1 only in state S_B
    assign f = (state == S_B);

    // g is 1 in S_D0, S_D1, and S_KEEP
    // Note: S_C3 is the cycle *after* the pattern, but the spec says "g should be set to 1 on the following clock cycle".
    // My trace: Pattern detected in S_C3. Next state S_D0.
    // In S_D0, g should be 1.
    // Let's verify the assign statement.
    // If state is S_D0, S_D1, S_KEEP -> g=1.
    assign g = (state == S_D0) || (state == S_D1) || (state == S_KEEP);

endmodule
